-- Testes gerais da Publike (08/11/2026; claude/plano-pedido-do-cliente-convites-e-testes.md, parte 2): Matemática do
-- dia a dia, Raciocínio lógico e Inglês básico, ao lado do Português. Pode rodar de novo.
-- Entram em revisão (publicado = false): o admin confere em Admin › Testes e publica. Rodar de novo atualiza as
-- questões e não mexe no publicado. As opções são embaralhadas para o candidato (a certa vale 1 ponto).

insert into privado.avaliacoes_modelos (id, tipo, area, titulo, descricao, questoes, publicado)
values ('a7a10000-0000-4000-8000-000000000010', 'pratico', 'matematica', 'Teste prático Publike: Matemática do dia a dia', 'Troco, desconto, porcentagem, medidas e horas.', '[{"id": "q1", "enunciado": "Uma compra deu R$ 37,50 e o cliente pagou com R$ 50,00. Quanto é o troco?", "opcoes": [{"id": "a", "texto": "R$ 12,50", "pontos": 1}, {"id": "b", "texto": "R$ 13,50", "pontos": 0}, {"id": "c", "texto": "R$ 12,00", "pontos": 0}, {"id": "d", "texto": "R$ 22,50", "pontos": 0}]}, {"id": "q2", "enunciado": "Uma camiseta de R$ 80,00 está com 25% de desconto. Por quanto ela sai?", "opcoes": [{"id": "a", "texto": "R$ 60,00", "pontos": 1}, {"id": "b", "texto": "R$ 55,00", "pontos": 0}, {"id": "c", "texto": "R$ 65,00", "pontos": 0}, {"id": "d", "texto": "R$ 75,00", "pontos": 0}]}, {"id": "q3", "enunciado": "Uma caixa tem 12 pacotes. Quantos pacotes há em 7 caixas?", "opcoes": [{"id": "a", "texto": "84", "pontos": 1}, {"id": "b", "texto": "72", "pontos": 0}, {"id": "c", "texto": "74", "pontos": 0}, {"id": "d", "texto": "96", "pontos": 0}]}, {"id": "q4", "enunciado": "Uma receita usa 3 ovos para 2 bolos. Quantos ovos são precisos para 6 bolos?", "opcoes": [{"id": "a", "texto": "9", "pontos": 1}, {"id": "b", "texto": "6", "pontos": 0}, {"id": "c", "texto": "12", "pontos": 0}, {"id": "d", "texto": "8", "pontos": 0}]}, {"id": "q5", "enunciado": "Quantos mililitros (ml) há em 2,5 litros?", "opcoes": [{"id": "a", "texto": "2.500 ml", "pontos": 1}, {"id": "b", "texto": "250 ml", "pontos": 0}, {"id": "c", "texto": "25 ml", "pontos": 0}, {"id": "d", "texto": "25.000 ml", "pontos": 0}]}, {"id": "q6", "enunciado": "Você ganha R$ 1.800,00 por mês e paga R$ 450,00 de aluguel. Que parte do salário vai para o aluguel?", "opcoes": [{"id": "a", "texto": "Um quarto (1/4)", "pontos": 1}, {"id": "b", "texto": "Um terço (1/3)", "pontos": 0}, {"id": "c", "texto": "Metade (1/2)", "pontos": 0}, {"id": "d", "texto": "Um quinto (1/5)", "pontos": 0}]}, {"id": "q7", "enunciado": "Um produto custa R$ 4,90 a unidade. Quanto custam 3 unidades?", "opcoes": [{"id": "a", "texto": "R$ 14,70", "pontos": 1}, {"id": "b", "texto": "R$ 14,90", "pontos": 0}, {"id": "c", "texto": "R$ 13,70", "pontos": 0}, {"id": "d", "texto": "R$ 15,70", "pontos": 0}]}, {"id": "q8", "enunciado": "O estoque tinha 240 unidades. Saíram 85 e chegaram 40. Quantas unidades ficaram?", "opcoes": [{"id": "a", "texto": "195", "pontos": 1}, {"id": "b", "texto": "205", "pontos": 0}, {"id": "c", "texto": "115", "pontos": 0}, {"id": "d", "texto": "185", "pontos": 0}]}, {"id": "q9", "enunciado": "Na segunda foram 14 entregas, na terça 9 e na quarta 17. Quantas entregas nos três dias?", "opcoes": [{"id": "a", "texto": "40", "pontos": 1}, {"id": "b", "texto": "39", "pontos": 0}, {"id": "c", "texto": "41", "pontos": 0}, {"id": "d", "texto": "31", "pontos": 0}]}, {"id": "q10", "enunciado": "Uma sala tem 4 m de largura e 5 m de comprimento. Qual é a área do piso?", "opcoes": [{"id": "a", "texto": "20 m²", "pontos": 1}, {"id": "b", "texto": "18 m²", "pontos": 0}, {"id": "c", "texto": "9 m²", "pontos": 0}, {"id": "d", "texto": "25 m²", "pontos": 0}]}, {"id": "q11", "enunciado": "O preço de um produto subiu de R$ 20,00 para R$ 23,00. Quanto por cento ele subiu?", "opcoes": [{"id": "a", "texto": "15%", "pontos": 1}, {"id": "b", "texto": "3%", "pontos": 0}, {"id": "c", "texto": "23%", "pontos": 0}, {"id": "d", "texto": "10%", "pontos": 0}]}, {"id": "q12", "enunciado": "Você entra às 22h e trabalha 8 horas seguidas. A que horas sai?", "opcoes": [{"id": "a", "texto": "6h", "pontos": 1}, {"id": "b", "texto": "5h", "pontos": 0}, {"id": "c", "texto": "7h", "pontos": 0}, {"id": "d", "texto": "4h", "pontos": 0}]}]'::jsonb, false)
on conflict (id) do update
  set tipo = excluded.tipo, area = excluded.area, titulo = excluded.titulo, descricao = excluded.descricao,
      questoes = excluded.questoes, atualizado_em = now();

insert into privado.avaliacoes_modelos (id, tipo, area, titulo, descricao, questoes, publicado)
values ('a7a10000-0000-4000-8000-000000000011', 'pratico', 'raciocinio', 'Teste prático Publike: Raciocínio lógico', 'Sequências, ordem e conclusões do dia a dia.', '[{"id": "q1", "enunciado": "Qual número vem depois: 2, 4, 8, 16, …?", "opcoes": [{"id": "a", "texto": "32", "pontos": 1}, {"id": "b", "texto": "24", "pontos": 0}, {"id": "c", "texto": "20", "pontos": 0}, {"id": "d", "texto": "18", "pontos": 0}]}, {"id": "q2", "enunciado": "Qual número falta: 3, 6, 9, __, 15?", "opcoes": [{"id": "a", "texto": "12", "pontos": 1}, {"id": "b", "texto": "10", "pontos": 0}, {"id": "c", "texto": "11", "pontos": 0}, {"id": "d", "texto": "13", "pontos": 0}]}, {"id": "q3", "enunciado": "Ana chegou antes de Bruno. Bruno chegou antes de Carla. Quem chegou primeiro?", "opcoes": [{"id": "a", "texto": "Ana", "pontos": 1}, {"id": "b", "texto": "Bruno", "pontos": 0}, {"id": "c", "texto": "Carla", "pontos": 0}, {"id": "d", "texto": "Não dá para saber", "pontos": 0}]}, {"id": "q4", "enunciado": "Todos os entregadores da loja têm moto. João é entregador da loja. Então:", "opcoes": [{"id": "a", "texto": "João tem moto", "pontos": 1}, {"id": "b", "texto": "João não tem moto", "pontos": 0}, {"id": "c", "texto": "Todo dono de moto é entregador da loja", "pontos": 0}, {"id": "d", "texto": "Não dá para saber", "pontos": 0}]}, {"id": "q5", "enunciado": "Qual letra vem depois: A, C, E, G, …?", "opcoes": [{"id": "a", "texto": "I", "pontos": 1}, {"id": "b", "texto": "H", "pontos": 0}, {"id": "c", "texto": "J", "pontos": 0}, {"id": "d", "texto": "K", "pontos": 0}]}, {"id": "q6", "enunciado": "Hoje é quarta-feira. Que dia será daqui a 5 dias?", "opcoes": [{"id": "a", "texto": "Segunda-feira", "pontos": 1}, {"id": "b", "texto": "Domingo", "pontos": 0}, {"id": "c", "texto": "Terça-feira", "pontos": 0}, {"id": "d", "texto": "Sexta-feira", "pontos": 0}]}, {"id": "q7", "enunciado": "Pedro é o 4º de uma fila de 9 pessoas. Quantas pessoas estão atrás dele?", "opcoes": [{"id": "a", "texto": "5", "pontos": 1}, {"id": "b", "texto": "4", "pontos": 0}, {"id": "c", "texto": "6", "pontos": 0}, {"id": "d", "texto": "3", "pontos": 0}]}, {"id": "q8", "enunciado": "A caixa vermelha é maior que a azul. A azul é maior que a verde. Qual é a menor?", "opcoes": [{"id": "a", "texto": "A verde", "pontos": 1}, {"id": "b", "texto": "A azul", "pontos": 0}, {"id": "c", "texto": "A vermelha", "pontos": 0}, {"id": "d", "texto": "Não dá para saber", "pontos": 0}]}, {"id": "q9", "enunciado": "Qual palavra não combina com as outras?", "opcoes": [{"id": "a", "texto": "Cenoura", "pontos": 1}, {"id": "b", "texto": "Maçã", "pontos": 0}, {"id": "c", "texto": "Banana", "pontos": 0}, {"id": "d", "texto": "Laranja", "pontos": 0}]}, {"id": "q10", "enunciado": "Quando chove, a obra para. Hoje a obra não parou. O que dá para concluir?", "opcoes": [{"id": "a", "texto": "Hoje não choveu", "pontos": 1}, {"id": "b", "texto": "Hoje choveu", "pontos": 0}, {"id": "c", "texto": "A obra nunca para", "pontos": 0}, {"id": "d", "texto": "Nada", "pontos": 0}]}, {"id": "q11", "enunciado": "São 3 horas da tarde. Que horas serão daqui a 10 horas?", "opcoes": [{"id": "a", "texto": "1 hora da manhã", "pontos": 1}, {"id": "b", "texto": "11 horas da noite", "pontos": 0}, {"id": "c", "texto": "2 horas da manhã", "pontos": 0}, {"id": "d", "texto": "Meia-noite", "pontos": 0}]}, {"id": "q12", "enunciado": "Um pacote leva 2 minutos para ser embalado. Quantos pacotes dá para embalar em meia hora?", "opcoes": [{"id": "a", "texto": "15", "pontos": 1}, {"id": "b", "texto": "12", "pontos": 0}, {"id": "c", "texto": "30", "pontos": 0}, {"id": "d", "texto": "20", "pontos": 0}]}]'::jsonb, false)
on conflict (id) do update
  set tipo = excluded.tipo, area = excluded.area, titulo = excluded.titulo, descricao = excluded.descricao,
      questoes = excluded.questoes, atualizado_em = now();

insert into privado.avaliacoes_modelos (id, tipo, area, titulo, descricao, questoes, publicado)
values ('a7a10000-0000-4000-8000-000000000012', 'pratico', 'ingles', 'Teste prático Publike: Inglês básico', 'Palavras e frases de atendimento, placas e etiquetas.', '[{"id": "q1", "enunciado": "O cliente diz “Good morning”. O que ele disse?", "opcoes": [{"id": "a", "texto": "Bom dia", "pontos": 1}, {"id": "b", "texto": "Boa noite", "pontos": 0}, {"id": "c", "texto": "Obrigado", "pontos": 0}, {"id": "d", "texto": "Até logo", "pontos": 0}]}, {"id": "q2", "enunciado": "Na porta está escrito “PUSH”. O que você faz?", "opcoes": [{"id": "a", "texto": "Empurra", "pontos": 1}, {"id": "b", "texto": "Puxa", "pontos": 0}, {"id": "c", "texto": "Espera", "pontos": 0}, {"id": "d", "texto": "Bate", "pontos": 0}]}, {"id": "q3", "enunciado": "Numa placa, “Exit” quer dizer:", "opcoes": [{"id": "a", "texto": "Saída", "pontos": 1}, {"id": "b", "texto": "Entrada", "pontos": 0}, {"id": "c", "texto": "Proibido", "pontos": 0}, {"id": "d", "texto": "Banheiro", "pontos": 0}]}, {"id": "q4", "enunciado": "O cliente pergunta “How much is it?”. O que ele quer saber?", "opcoes": [{"id": "a", "texto": "O preço", "pontos": 1}, {"id": "b", "texto": "O horário", "pontos": 0}, {"id": "c", "texto": "O tamanho", "pontos": 0}, {"id": "d", "texto": "O caminho", "pontos": 0}]}, {"id": "q5", "enunciado": "O cliente diz “Thank you”. Qual é a resposta educada?", "opcoes": [{"id": "a", "texto": "You''re welcome", "pontos": 1}, {"id": "b", "texto": "Good night", "pontos": 0}, {"id": "c", "texto": "I''m sorry", "pontos": 0}, {"id": "d", "texto": "Excuse me", "pontos": 0}]}, {"id": "q6", "enunciado": "Na porta da loja, “Open” quer dizer:", "opcoes": [{"id": "a", "texto": "Aberto", "pontos": 1}, {"id": "b", "texto": "Fechado", "pontos": 0}, {"id": "c", "texto": "Em reforma", "pontos": 0}, {"id": "d", "texto": "Promoção", "pontos": 0}]}, {"id": "q7", "enunciado": "Um turista pergunta “Where is the bathroom?”. O que ele procura?", "opcoes": [{"id": "a", "texto": "O banheiro", "pontos": 1}, {"id": "b", "texto": "A saída", "pontos": 0}, {"id": "c", "texto": "O caixa", "pontos": 0}, {"id": "d", "texto": "O elevador", "pontos": 0}]}, {"id": "q8", "enunciado": "“Small”, “medium” e “large” são:", "opcoes": [{"id": "a", "texto": "Tamanhos", "pontos": 1}, {"id": "b", "texto": "Cores", "pontos": 0}, {"id": "c", "texto": "Sabores", "pontos": 0}, {"id": "d", "texto": "Preços", "pontos": 0}]}, {"id": "q9", "enunciado": "Na etiqueta da roupa está “Do not wash”. O que quer dizer?", "opcoes": [{"id": "a", "texto": "Não lavar", "pontos": 1}, {"id": "b", "texto": "Lavar à mão", "pontos": 0}, {"id": "c", "texto": "Lavar com água fria", "pontos": 0}, {"id": "d", "texto": "Secar à sombra", "pontos": 0}]}, {"id": "q10", "enunciado": "O cliente pergunta “Can I pay by card?”. O que ele quer?", "opcoes": [{"id": "a", "texto": "Pagar com cartão", "pontos": 1}, {"id": "b", "texto": "Pagar em dinheiro", "pontos": 0}, {"id": "c", "texto": "Pedir desconto", "pontos": 0}, {"id": "d", "texto": "Trocar o produto", "pontos": 0}]}, {"id": "q11", "enunciado": "Uma placa diz “Wet floor”. Ela avisa que:", "opcoes": [{"id": "a", "texto": "O piso está molhado", "pontos": 1}, {"id": "b", "texto": "O piso é novo", "pontos": 0}, {"id": "c", "texto": "É o andar de cima", "pontos": 0}, {"id": "d", "texto": "A área está fechada", "pontos": 0}]}, {"id": "q12", "enunciado": "Qual número é “fifteen”?", "opcoes": [{"id": "a", "texto": "15", "pontos": 1}, {"id": "b", "texto": "50", "pontos": 0}, {"id": "c", "texto": "5", "pontos": 0}, {"id": "d", "texto": "16", "pontos": 0}]}]'::jsonb, false)
on conflict (id) do update
  set tipo = excluded.tipo, area = excluded.area, titulo = excluded.titulo, descricao = excluded.descricao,
      questoes = excluded.questoes, atualizado_em = now();

notify pgrst, 'reload schema';
